// Help guide CMS routes and helpers.
if (!function_exists('ao_help_slug')) {
    function ao_help_slug($text){
        $text=mb_strtolower(trim((string)$text),'UTF-8');
        $map=['ı'=>'i','ğ'=>'g','ü'=>'u','ş'=>'s','ö'=>'o','ç'=>'c'];
        $text=strtr($text,$map);
        $text=preg_replace('/[^a-z0-9]+/','-',$text);
        return trim($text,'-') ?: 'yardim';
    }
    function ao_help_table_exists($table){ try{ db()->query('SELECT 1 FROM `'.$table.'` LIMIT 1'); return true; }catch(Throwable $e){ return false; } }
    function ao_help_columns($table){ try{ return array_map(fn($r)=>$r['Field']??$r[0], db()->query('SHOW COLUMNS FROM `'.$table.'`')->fetchAll()); }catch(Throwable $e){ return []; } }
