                db()->prepare("INSERT INTO help_articles (category_id,title,slug,summary,content,related_label,related_route,tags,status,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?, 'published',NOW(),NOW()) ON DUPLICATE KEY UPDATE summary=VALUES(summary),content=VALUES(content),related_label=VALUES(related_label),related_route=VALUES(related_route),tags=VALUES(tags),updated_at=NOW()")->execute([$licCat,'Ahost One lisans sistemi nasıl çalışır?','ahost-one-lisans-sistemi-nasil-calisir','Domain, package name, purchase code ve offline-first lisans mantığı.',$licContent,'License Center’a Git','admin/license-center','lisans,codecanyon,purchase code,domain,package name,android,offline']);
