    function ao_help_categories(){ ao_help_install(); try{return db()->query('SELECT * FROM help_categories ORDER BY sort_order,id')->fetchAll() ?: [];}catch(Throwable $e){return [];} }
    function ao_help_articles($where='1=1',$params=[]){ ao_help_install(); try{$st=db()->prepare('SELECT a.*,c.title category_title,c.icon category_icon FROM help_articles a LEFT JOIN help_categories c ON c.id=a.category_id WHERE '.$where.' ORDER BY a.sort_order,a.id DESC'); $st->execute($params); return $st->fetchAll()?:[];}catch(Throwable $e){return [];} }
    function ao_help_article($id){ ao_help_install(); try{$st=db()->prepare('SELECT a.*,c.title category_title,c.icon category_icon FROM help_articles a LEFT JOIN help_categories c ON c.id=a.category_id WHERE a.id=? LIMIT 1'); $st->execute([(int)$id]); return $st->fetch() ?: null;}catch(Throwable $e){return null;} }
    function ao_help_cat_options($selected=0){ $html=''; foreach(ao_help_categories() as $c){ $sel=((int)$c['id']==(int)$selected)?' selected':''; $html.='<option value="'.(int)$c['id'].'"'.$sel.'>'.e(($c['icon']?:'❔').' '.$c['title']).'</option>'; } return $html; }
}

if (in_array($route,['admin/help-guide','admin/help-center'],true)) { require_admin(); ao_help_install();
    $q=trim((string)($_GET['q']??''));
    $articles=$q!==''?ao_help_articles('(a.title LIKE ? OR a.summary LIKE ? OR a.content LIKE ? OR a.tags LIKE ?)',array_fill(0,4,'%'.$q.'%')):ao_help_articles('a.status<>?',['deleted']);
    $minutes=[5,15,10,5,10,15,8,7,6,10];
    $topicCards=''; $manageRows='';
    foreach(array_slice($articles,0,60) as $i=>$a){
        $summary=trim((string)($a['summary']??'')); if($summary==='') $summary=trim(mb_substr(strip_tags((string)($a['content']??'')),0,120,'UTF-8'));
        $minute=$minutes[$i % count($minutes)];
        $topicCards.='<a class="ao-help-topic-card" href="'.url('admin/help-guide/article?id='.(int)$a['id']).'"><span class="ao-help-topic-no">'.($i+1).'</span><span class="ao-help-topic-copy"><strong>'.e($a['title']).'</strong><small>'.e($summary).'</small><em>'.$minute.' dk</em></span></a>';
        $delete='<form method="post" action="'.url('admin/help-guide/articles/delete').'" onsubmit="return confirm(\'Yardım konusu silinsin mi?\')">'.csrf_field().'<input type="hidden" name="id" value="'.(int)$a['id'].'"><button class="ao-mini-btn soft">Sil</button></form>';
        $manageRows.='<div class="ao-help-manage-row"><div><b>'.e($a['title']).'</b><small>'.e($a['category_title']??'Kategorisiz').'</small></div><div class="ao-help-manage-actions"><a class="ao-mini-btn soft" href="'.url('admin/help-guide/articles/edit?id='.(int)$a['id']).'">Düzenle</a>'.$delete.'</div></div>';
    }
    if($topicCards==='') $topicCards='<div class="ao-card">Henüz yardım konusu yok. Sağ taraftan yeni yardım ekleyebilirsiniz.</div>';
    if($manageRows==='') $manageRows='<p class="ao-help-empty">Henüz yönetilecek yardım yok.</p>';
    $search='<form class="ao-help-compact-search" method="get" action="'.url('admin/help-guide').'"><input name="q" value="'.e($q).'" placeholder="Yardım konusu ara"><button class="ao-mini-btn">Ara</button></form>';
    $side='<aside class="ao-help-manage-panel"><div class="ao-help-manage-head"><h3>Yönetim</h3><a class="ao-btn" href="'.url('admin/help-guide/articles/create').'">+ Yeni Yardım Ekle</a></div>'.$search.'<a class="ao-mini-btn soft" href="'.url('admin/help-guide/categories').'">Kategoriler</a><div class="ao-help-manage-list">'.$manageRows.'</div></aside>';
    $html='<div class="ao-page-head"><div><h2>Yardım Kılavuzu</h2><p>Yardım konuları kartlar halinde listelenir. Karta tıklayınca yapılacaklar ekranı açılır.</p></div></div><div class="ao-help"><section class="ao-help-main-panel"><div class="ao-help-topic-grid">'.$topicCards.'</div></section>'.$side.'</div>';
    ao_admin_fallback_shell('Yardım Kılavuzu',$html);
}

