if ($_SERVER['REQUEST_METHOD']==='POST' && $route==='admin/help-guide/categories/save') { require_admin(); verify_csrf(); ao_help_install(); $id=(int)($_POST['id']??0); $title=trim((string)($_POST['title']??'')); $slug=ao_help_slug($title); $data=[$title,$slug,trim((string)($_POST['icon']??'❔')),trim((string)($_POST['description']??'')),(int)($_POST['sort_order']??0),(int)($_POST['is_active']??1)]; try{ if($id>0){ db()->prepare('UPDATE help_categories SET title=?,slug=?,icon=?,description=?,sort_order=?,is_active=?,updated_at=NOW() WHERE id=?')->execute([...$data,$id]); } else { db()->prepare('INSERT INTO help_categories (title,slug,icon,description,sort_order,is_active,created_at,updated_at) VALUES (?,?,?,?,?,?,NOW(),NOW())')->execute($data); } flash('success','Yardım kategorisi kaydedildi.'); }catch(Throwable $e){ flash('error','Kategori kaydedilemedi: '.$e->getMessage()); } redirect_to('admin/help-guide/categories'); }
