    }
    $where='a.status<>?'; $params=['deleted']; if(isset($_GET['category_id'])){ $where.=' AND a.category_id=?'; $params[]=(int)$_GET['category_id']; }
    $cards='<a class="ao-card ao-help-add-card" href="'.url('admin/help-guide/articles/create').'"><h3>+ Yeni Ekle</h3><p>Yeni yardım konusu oluştur, açıklamasını ve ilgili ayar bağlantısını belirle.</p><span class="ao-mini-btn">Yeni Makale</span></a>';
    foreach(ao_help_articles($where,$params) as $a){
        $rr=trim((string)($a['related_route']??''));
        $href=$rr!==''?(preg_match('#^https?://#',$rr)?$rr:url($rr)):'';
        $go=$href!==''?'<a class="ao-mini-btn" href="'.e($href).'">'.e($a['related_label']?:'İlgili Ayara Git').'</a>':'';
        $delete='<form method="post" action="'.url('admin/help-guide/articles/delete').'" onsubmit="return confirm(&quot;Makale silinsin mi?&quot;)">'.csrf_field().'<input type="hidden" name="id" value="'.(int)$a['id'].'"><button class="ao-mini-btn soft">Sil</button></form>';
        $cards.='<article class="ao-card ao-help-card"><div class="ao-help-card-head"><small>'.e(($a['category_icon']??'').' '.($a['category_title']??'-')).'</small><details class="ao-help-options"><summary>Seçenekler</summary><div><a class="ao-mini-btn soft" href="'.url('admin/help-guide/articles/edit?id='.(int)$a['id']).'">Düzenle</a>'.$delete.'</div></details></div><a href="'.url('admin/help-guide/article?id='.(int)$a['id']).'" style="display:block;text-decoration:none;color:inherit"><h3>'.e($a['title']).'</h3><p>'.e($a['summary']??'').'</p></a><div class="ao-actions">'.$go.'</div></article>';
    }
    ao_admin_fallback_shell('Yardım Makaleleri','<div class="ao-page-head"><div><h2>Yardım Makaleleri</h2><p>Karta tıklayınca yardım içeriği doğrudan açılır. Düzenle ve sil işlemleri Seçenekler menüsündedir.</p></div><a class="ao-btn" href="'.url('admin/help-guide/articles/create').'">+ Yeni Makale</a></div><div class="ao-help-grid">'.$cards.'</div>');
}
if ($_SERVER['REQUEST_METHOD']==='POST' && $route==='admin/help-guide/articles/save') { require_admin(); verify_csrf(); ao_help_install(); $id=(int)($_POST['id']??0); $title=trim((string)($_POST['title']??'')); $slug=ao_help_slug($title); $data=[(int)($_POST['category_id']??0),$title,$slug,trim((string)($_POST['summary']??'')),trim((string)($_POST['content']??'')),trim((string)($_POST['related_label']??'')),trim((string)($_POST['related_route']??'')),trim((string)($_POST['tags']??'')),trim((string)($_POST['status']??'published'))]; try{ if($id>0){ db()->prepare('UPDATE help_articles SET category_id=?,title=?,slug=?,summary=?,content=?,related_label=?,related_route=?,tags=?,status=?,updated_at=NOW() WHERE id=?')->execute([...$data,$id]); } else { db()->prepare('INSERT INTO help_articles (category_id,title,slug,summary,content,related_label,related_route,tags,status,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,NOW(),NOW())')->execute($data); } flash('success','Yardım makalesi kaydedildi.'); }catch(Throwable $e){ flash('error','Makale kaydedilemedi: '.$e->getMessage()); } redirect_to('admin/help-guide'); }
if ($_SERVER['REQUEST_METHOD']==='POST' && $route==='admin/help-guide/articles/delete') { require_admin(); verify_csrf(); ao_help_install(); try{ db()->prepare('DELETE FROM help_articles WHERE id=?')->execute([(int)($_POST['id']??0)]); flash('success','Makale silindi.'); }catch(Throwable $e){ flash('error','Makale silinemedi.'); } redirect_to('admin/help-guide'); }
if ($route==='admin/help-guide/article') { require_admin(); ao_help_install(); $a=ao_help_article((int)($_GET['id']??0)); if(!$a) ao_admin_fallback_shell('Yardım Makalesi','<div class="ao-card">Makale bulunamadı.</div>'); try{ db()->prepare('UPDATE help_articles SET views=views+1 WHERE id=?')->execute([(int)$a['id']]); }catch(Throwable $e){ error_log('[ao] '.$e->getMessage().' @ '.$e->getFile().':'.$e->getLine()); }
    $rr=trim((string)($a['related_route']??'')); $go=''; if($rr!==''){ $href=preg_match('#^https?://#',$rr)?$rr:url($rr); $go='<a class="ao-btn" href="'.e($href).'">'.e($a['related_label']?:'İlgili Ayar Alanına Git').'</a>'; }
    $raw=trim((string)($a['content']??'')); $lines=array_values(array_filter(array_map('trim',preg_split('/\R+/', $raw))));
    $steps=''; $note=''; foreach($lines as $ln){ if(mb_strlen($ln,'UTF-8')<180 && preg_match('/^(not|uyarı|ipucu|bilgilendirme)[:：]/iu',$ln)){ $note=preg_replace('/^(not|uyarı|ipucu|bilgilendirme)[:：]\s*/iu','',$ln); continue; } $steps.='<li>'.e(preg_replace('/^\d+[\.)]\s*/','',$ln)).'</li>'; }
    if($steps==='') $steps='<li>'.e($a['summary'] ?: 'Bu yardım konusu için ilgili ayar sayfasına gidin ve alanları kontrol edin.').'</li>';
    if($note==='') $note='Değişiklikten sonra sayfayı yenileyin ve gerekirse önbelleği temizleyin.';
    $stepNo=max(1,(int)ceil(((int)($a['sort_order']??10))/10));
    $cleanTitle=preg_replace('/\s+nasıl yapılır\??$/iu','',(string)$a['title']);
    $stepTitle='Adım '.$stepNo.': '.$cleanTitle;
    $next=''; try{ $n=db()->prepare("SELECT id,title FROM help_articles WHERE status='published' AND id<>? AND (category_id=? OR ?=0) ORDER BY sort_order ASC,id ASC LIMIT 1"); $n->execute([(int)$a['id'],(int)($a['category_id']??0),(int)($a['category_id']??0)]); $nx=$n->fetch(); if($nx){ $next='<a class="ao-btn" href="'.url('admin/help-guide/article?id='.(int)$nx['id']).'">Sonraki: '.e($nx['title']).'</a>'; } }catch(Throwable $e){ error_log('[ao] '.$e->getMessage().' @ '.$e->getFile().':'.$e->getLine()); }
    if($next==='') $next='<a class="ao-btn" href="'.url('admin/help-guide').'">Sonraki: Yardım Kılavuzu</a>';
    $delete='<form method="post" action="'.url('admin/help-guide/articles/delete').'" onsubmit="return confirm(\'Yardım konusu silinsin mi?\')">'.csrf_field().'<input type="hidden" name="id" value="'.(int)$a['id'].'"><button class="ao-mini-btn soft">Sil</button></form>';
    $side='<aside class="ao-help-manage-panel"><div class="ao-help-manage-head"><h3>Yönetim</h3><a class="ao-btn" href="'.url('admin/help-guide/articles/create').'">+ Yeni Yardım Ekle</a></div><div class="ao-help-current-topic"><b>'.e($a['title']).'</b><small>'.e($a['category_title']??'Kategorisiz').'</small><div class="ao-help-manage-actions"><a class="ao-mini-btn soft" href="'.url('admin/help-guide/articles/edit?id='.(int)$a['id']).'">Düzenle</a>'.$delete.'</div></div></aside>';
    $html='<div class="ao-help ao-help-detail"><section class="ao-help-detail-card"><h1>Yapılacaklar</h1><p class="ao-help-detail-summary">'.e($a['summary']??$stepTitle).'</p><ol class="ao-help-todo-list">'.$steps.'</ol><div class="ao-help-note">'.e($note).'</div>'.($go?'<div class="ao-help-related">'.$go.'</div>':'').'<div class="ao-help-detail-actions"><a class="ao-btn soft" href="'.url('admin/help-guide').'">Ana Sayfa</a>'.$next.'</div></section>'.$side.'</div>';
    ao_admin_fallback_shell($a['title'],$html);
}

